class Solution:
    def closestMeetingNode(self, edges: list[int], node1: int, node2: int) -> int:
        def get_dists(start):
            dist = [-1] * len(edges)
            cur = start
            d = 0
            while cur != -1 and dist[cur] == -1:
                dist[cur] = d
                d += 1
                cur = edges[cur]
            return dist
        d1 = get_dists(node1)
        d2 = get_dists(node2)
        min_dist = float('inf')
        ans = -1
        for i in range(len(edges)):
            if d1[i] != -1 and d2[i] != -1:
                mx = max(d1[i], d2[i])
                if mx < min_dist:
                    min_dist = mx
                    ans = i
        return ans

class Solution {
public:
    int closestMeetingNode(std::vector<int>& edges, int node1, int node2) {
        int n = edges.size();
        auto get_dists = [&](int start) {
            std::vector<int> dist(n, -1);
            int cur = start, d = 0;
            while (cur != -1 && dist[cur] == -1) {
                dist[cur] = d++;
                cur = edges[cur];
            }
            return dist;
        };
        std::vector<int> d1 = get_dists(node1);
        std::vector<int> d2 = get_dists(node2);
        int min_dist = 1e9, ans = -1;
        for (int i = 0; i < n; ++i) {
            if (d1[i] != -1 && d2[i] != -1) {
                int mx = std::max(d1[i], d2[i]);
                if (mx < min_dist) {
                    min_dist = mx;
                    ans = i;
                }
            }
        }
        return ans;
    }
};

class Solution {
    public int closestMeetingNode(int[] edges, int node1, int node2) {
        int n = edges.length;
        int[] d1 = getDists(edges, node1, n);
        int[] d2 = getDists(edges, node2, n);
        int minDist = Integer.MAX_VALUE, ans = -1;
        for (int i = 0; i < n; ++i) {
            if (d1[i] != -1 && d2[i] != -1) {
                int mx = Math.max(d1[i], d2[i]);
                if (mx < minDist) {
                    minDist = mx;
                    ans = i;
                }
            }
        }
        return ans;
    }
    private int[] getDists(int[] edges, int start, int n) {
        int[] dist = new int[n];
        java.util.Arrays.fill(dist, -1);
        int cur = start, d = 0;
        while (cur != -1 && dist[cur] == -1) {
            dist[cur] = d++;
            cur = edges[cur];
        }
        return dist;
    }
}

